#include <iostream>
#include <string>

struct Part {
    unsigned int partNumber{0};
    char partName[25]{""};
};

void printPartByPtr(const Part* ptr) {
    if (ptr != nullptr) {
        std::cout << "Part #" << ptr->partNumber << ": " << ptr->partName << "\n";
    }
}

int main() {
    // Khởi tạo struct và mảng struct
    Part a{101, "Gearbox"};
    Part b[10]{}; // Các phần tử còn lại tự động điền 0

    // Thao tác gán hợp lệ giữa hai struct cùng kiểu
    b[3] = a;

    // Con trỏ trỏ đến mảng
    Part* ptr = b;

    // In phần tử thứ 3 thông qua con trỏ và toán tử ->
    printPartByPtr(ptr + 3);

    return 0;
}

#include <iostream>

// Khai báo struct sử dụng Bit Fields
struct BitFlags {
    unsigned int isReady    : 1; // 1 bit (0 hoặc 1)
    unsigned int isRunning  : 1; // 1 bit
    unsigned int errorCode  : 4; // 4 bit (giá trị 0-15)
};

// Hàm nhân số nguyên không dấu với 2^pow bằng toán tử dịch trái (<<)
unsigned int power2(unsigned int number, unsigned int pow) {
    return number << pow;
}

int main() {
    BitFlags flags{1, 0, 7};
    std::cout << "Ready: " << flags.isReady
              << ", Running: " << flags.isRunning
              << ", Error: " << flags.errorCode << "\n";

    // Thao tác dịch bit
    unsigned int val = 5; // 5 * 2^3 = 40
    unsigned int res = power2(val, 3);
    std::cout << val << " * 2^3 = " << res << "\n";

    // Mặt nạ bit (Masking)
    unsigned int mask = 0x0F;
    unsigned int data = 0xAB;
    std::cout << "Masked data: " << std::hex << (data & mask) << "\n";

    return 0;
}

#include <iostream>
#include <cstdlib>
#include <cctype>

// Parses and validates an integer according to CERT INT05-C guidelines
bool parse_and_validate_int(const char* str, long min_val, long max_val, long& out_val) {
    if (str == nullptr || *str == '\0') {
        return false;
    }

    char* endptr = nullptr;
    long result = std::strtol(str, &endptr, 10);

    // 1. Detect if no digits were parsed at all
    if (endptr == str) {
        return false;
    }

    // 2. Ensure no trailing invalid characters (ignore trailing whitespace)
    while (*endptr != '\0') {
        if (!std::isspace(static_cast<unsigned char>(*endptr))) {
            return false;
        }
        ++endptr;
    }

    // 3. Verify domain boundaries
    if (result < min_val || result > max_val) {
        return false;
    }

    out_val = result;
    return true;
}

int main() {
    const char* sample_inputs[] = {"102", "8000000000", "27.43", "FOVR", "42"};
    const long MIN_BOUND = 1;
    const long MAX_BOUND = 100;

    for (const char* input : sample_inputs) {
        long value = 0;
        if (parse_and_validate_int(input, MIN_BOUND, MAX_BOUND, value)) {
            std::cout << "Input '" << input << "' -> Valid: " << value << "\n";
        } else {
            std::cout << "Input '" << input << "' -> Invalid!\n";
        }
    }

    return 0;
}

#include <iostream>
#include <cstring>
#include <cctype>

int main() {
    // 1. Correct comparison check using std::strcmp
    const char* s1 = "Apple";
    const char* s2 = "Apple";
    if (std::strcmp(s1, s2) == 0) {
        std::cout << "s1 and s2 are equal\n";
    }

    // 2. Safe memory move on overlapping memory segments
    char buffer[20] = "ABCDEFGHIJ";
    // Shift first 5 characters ("ABCDE") 2 positions forward
    std::memmove(buffer + 2, buffer, 5);
    std::cout << "Overlapping memmove result: " << buffer << "\n";

    // 3. String length measurement (excluding '\0')
    std::cout << "Buffer string length: " << std::strlen(buffer) << "\n";

    // 4. Character conversion with proper unsigned char cast
    char lower_ch = 'k';
    char upper_ch = static_cast<char>(std::toupper(static_cast<unsigned char>(lower_ch)));
    std::cout << "Uppercase of '" << lower_ch << "' is '" << upper_ch << "'\n";

    return 0;
}

#include <iostream>
#include <cstring>
#include <string_view>

int main() {
    // Inspecting standard error message for ENOENT (typically error code 2)
    int errCode = 2;
    std::cout << "strerror(" << errCode << "): " << std::strerror(errCode) << "\n";

    // Using strlen on C-style strings
    const char* str1 = "abcdefghijklmnopqrstuvwxyz";
    const char* str2 = "four";
    const char* str3 = "Boston";

    std::cout << "strlen(\"" << str1 << "\"): " << std::strlen(str1) << "\n";
    std::cout << "strlen(\"" << str2 << "\"): " << std::strlen(str2) << "\n";
    std::cout << "strlen(\"" << str3 << "\"): " << std::strlen(str3) << "\n";

    // C++17 string_view equivalent
    std::string_view sv = str1;
    std::cout << "string_view length: " << sv.length() << "\n";

    return 0;
}
